import random, subprocess, ipaddress, os, sys
BIN='/work/submit/planb64'

def rand_prefix():
    L=random.choice([0,1,2,3,7,8,16,24,31,32,33,47,48,63,64,random.randint(0,64)])
    # random upper bits
    val=random.getrandbits(128)
    # build address with host bits zero for clarity, ipaddress handles
    if L==0:
        net=ipaddress.IPv6Network('::/0')
    else:
        # create network from int
        mask=((1<<128)-1) ^ ((1<<(128-L))-1)
        net=ipaddress.IPv6Network((val & mask, L))
    return net

def compile_expected(fib):
    # fib: list of (network_int, L, hop)
    # produce minimal rows with independent sweep using half-open [s,e+1)
    ev=[]
    for (net,L,hop) in fib:
        s=net  # top 64 key: net>>64? but net is 128-bit normalized; key = net >>64 (lower host zero)
        key=(net>>64) & ((1<<64)-1)
        if L==0:
            end=(1<<64)-1
        else:
            size=1<<(64-L)
            end=key+size-1
        ev.append((key,1,L,hop))
        if end+1 <= (1<<64)-1:
            ev.append((end+1,0,L,hop))
    ev.sort(key=lambda x:(x[0],x[1]))
    rows=[]
    active={}
    cur=(-1,-1)
    idx=0
    n=len(ev)
    if n==0:
        return [(0,-1,-1)]
    if ev[0][0]==0:
        j=0
        while j<n and ev[j][0]==0:
            _,t,L,h=ev[j]
            if t==0: active.pop(L,None)
            else: active[L]=h
            j+=1
        idx=j
        best=None
        for l in sorted(active,reverse=True):
            best=(active[l],l);break
        if best is None: best=(-1,-1)
        cur=best
        rows.append((0,)+best)
    else:
        rows.append((0,-1,-1)); cur=(-1,-1)
    while idx<n:
        c=ev[idx][0]; j=idx
        while j<n and ev[j][0]==c:
            _,t,L,h=ev[j]
            if t==0: active.pop(L,None)
            else: active[L]=h
            j+=1
        idx=j
        best=None
        for l in sorted(active,reverse=True):
            best=(active[l],l);break
        if best is None: best=(-1,-1)
        if best!=cur:
            rows.append((c,)+best); cur=best
    return rows

def ser(rows):
    out='PLANB64 1\n%d\n'%len(rows)
    for s,h,l in rows:
        out+='%016x %d %d\n'%(s,h,l)
    return out

def lpm(fib,key):
    best=None
    for (net,L,hop) in fib:
        if L==0:
            match=True
        else:
            mask=((1<<L)-1)<<(64-L)
            match=(key & mask)==((net>>64)&mask)
        if match:
            if best is None or L>best[1]:
                best=(hop,L)
    return best if best else (-1,-1)

for trial in range(300):
    nf=random.randint(0,40)
    seen=set(); fib=[]
    lines=[]
    for _ in range(nf):
        net=rand_prefix(); L=net.prefixlen
        key=(int(net.network_address)>>64)&((1<<64)-1)
        if (key,L) in seen: continue
        seen.add((key,L))
        hop=random.randint(0,2**32-1)
        fib.append((int(net.network_address),L,hop))
        lines.append('%s %d'%(net,hop))
    random.shuffle(lines)
    open('/tmp/fib.txt','w').write('\n'.join(lines)+('\n' if lines else ''))
    r=subprocess.run([BIN,'build','/tmp/fib.txt','/tmp/img.idx'],capture_output=True)
    if r.returncode!=0:
        print('BUILD FAIL',trial,r.stderr); print('\n'.join(lines)); sys.exit()
    got=open('/tmp/img.idx').read()
    exp=ser(compile_expected(fib))
    if got!=exp:
        print('IMAGE MISMATCH trial',trial); print('\n'.join(lines)); print('GOT:\n',got); print('EXP:\n',exp); sys.exit()
    # trace
    qs=[]
    tr=[]
    for _ in range(random.randint(0,30)):
        addr=random.getrandbits(128)
        qs.append(addr); tr.append(str(ipaddress.IPv6Address(addr)))
    open('/tmp/trace.txt','w').write('\n'.join(tr)+('\n' if tr else ''))
    exp_out=''.join('%d %d\n'%lpm(fib,(q>>64)&((1<<64)-1)) for q in qs)
    for mode in (['scalar'],['batch',str(random.randint(1,256))]):
        r=subprocess.run([BIN,'lookup','/tmp/img.idx','/tmp/trace.txt']+mode,capture_output=True)
        if r.returncode!=0 or r.stdout.decode()!=exp_out:
            print('LOOKUP MISMATCH',trial,mode); print('got',r.stdout); print('exp',exp_out); print(r.stderr); sys.exit()
print('ALL FUZZ OK')
